UPDATE hospital_bedoc_list 
SET 
    search_doctor_site = #{foundProfileUrl},
    search_hospital_name = #{findHospitalName}
WHERE found_hospital_hid = #{hid} and bedoc_doctorname = #{doctorname} and bedoc_deptname = #{deptname}

UPDATE doctor_basic 
SET 
    new_doctor_url = #{foundProfileUrl},
    new_hospitalname = #{findHospitalName}
WHERE rid_long = #{rid_long}
